import SnackBar from "@/components/SnackBar.vue";
import GoogleMaps from "@/components/GoogleMaps.vue";
import GoogleAddressAutocomplete from "@/components/GoogleAddressAutocomplete.vue";
export default {
  props: {
    addGeoLocationDialog: Boolean,
    location_type: String
  },
  components: {
    SnackBar,
    GoogleMaps,
    GoogleAddressAutocomplete
  },
  data() {
    return {
      SnackBarComponent: {},
      zoom: 8,
      polygonPaths: [],
      locationName: "",
      geoLattitude: "",
      geoLongitude: "",
      loading: false,
      search: "",
      search1: "",
      currentPlace: null,
      markers: [],
      locationHead: "",
      defaultCenter: {
        lat: 0,
        lng: 0
      },
      latt: "",
      longg: "",
      mapMarkers: [],
      mapCenter: {
        lat: 0,
        lng: 0
      },
      locationAddress: "",
      googleApiKey: "AIzaSyCiwPvMBsTQy6yiTJDvDkqZPIWdDerOcRI"
    };
  },
  methods: {
    onMapsLoaded(google) {
      // console.log("Google Maps loaded successfully");
    },
    onMarkerClick(markerData) {
      this.mapCenter = markerData.position;
    },
    clearpolyarray() {
      this.polygonPaths = [];
    },
    async initMap() {
      await GoogleMap.loaded();
      this.map = this.$refs.map.$mapObject;
    },
    placeMarker(event) {
      this.polygonPaths.push({
        lat: event.latLng.lat(),
        lng: event.latLng.lng()
      });
    },
    updatePolygon(event) {
      const newPaths = event.getPath().getArray().map(vertex => ({
        lat: vertex.lat(),
        lng: vertex.lng()
      }));
      this.polygonPaths = newPaths;
    },
    clearField() {
      this.search = "";

      // Check if currentPlace exists before trying to add marker
      if (this.currentPlace && this.currentPlace.geometry && this.currentPlace.geometry.location) {
        this.addMarker();
      } else {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Please select a location from the search results first",
          timeout: 2000,
          Top: true
        };
      }
    },
    addMarker() {
      if (this.currentPlace) {
        // this.locationName = this.currentPlace.formatted_address;
        this.mapMarkers = [];
        var marker = {
          position: {
            lat: this.currentPlace.geometry.location.lat(),
            lng: this.currentPlace.geometry.location.lng()
          }
        };
        this.mapMarkers = [marker]; // Force reactivity by creating new array
        this.geoLattitude = marker.position.lat;
        this.geoLongitude = marker.position.lng;

        // Update map center
        this.mapCenter = marker.position;
      }
    },
    callposition(latLng) {
      this.mapMarkers = [];
      var marker = {
        position: {
          lat: latLng.lat,
          lng: latLng.lng
        }
      };
      this.mapMarkers = [marker]; // Force reactivity by creating new array
      this.geoLattitude = marker.position.lat;
      this.geoLongitude = marker.position.lng;

      // Update map center
      this.mapCenter = marker.position;
    },
    setPlace(placeData) {
      // console.log("Place selected:", placeData);

      if (placeData && placeData.location) {
        this.currentPlace = placeData.place;
        this.search = placeData.formatted_address;

        // Add marker to map - use Vue.set or spread operator to ensure reactivity
        this.mapMarkers = [];
        var marker = {
          position: {
            lat: placeData.location.lat,
            lng: placeData.location.lng
          }
        };
        this.mapMarkers = [marker]; // Force reactivity by creating new array
        this.geoLattitude = marker.position.lat;
        this.geoLongitude = marker.position.lng;

        // Update map center to the new marker
        this.mapCenter = marker.position;

        // Update address if available
        if (placeData.formatted_address) {
          this.locationAddress = placeData.formatted_address;
        }

        // console.log("Marker added:", marker);
      } else {
        console.warn("No valid place data received");
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Please select a valid location from the search results",
          timeout: 2000,
          Top: true
        };
      }
    },
    close_dialog() {
      this.$emit("clicked", 0);
      // this.$refs.form.resetValidation();
      this.locationName = "";
      this.mapMarkers = [];
      this.geoLattitude = "";
      this.geoLongitude = "";
      this.search = "";
      this.locationAddress = "";
    },
    validate_data() {
      if (!this.currentPlace || !this.currentPlace.formatted_address) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Please select a valid location before saving.",
          timeout: 2000,
          Top: true
        };
        return;
      }
      const locationData = {
        location_type: this.location_type,
        address_Detail: this.currentPlace.formatted_address,
        geo_lat: this.geoLattitude,
        geo_long: this.geoLongitude
      };
      this.$emit("savelocation", locationData);
      this.locationName = "";
      this.mapMarkers = [];
      this.geoLattitude = "";
      this.geoLongitude = "";
      this.search = "";
      this.locationAddress = "";
      this.currentPlace = null;
      this.polygonPaths = [];
      this.mapCenter = {
        lat: 0,
        lng: 0
      };
      this.mapMarkers = [];
      this.geoLattitude = "";
      this.geoLongitude = "";
      this.search = "";
      this.locationAddress = "";
    }
  }
};
